mapper.select:
SELECT n.notice_id AS noticeId, n.course_id AS courseId, IFNULL(c.course_name, '综合提醒') AS courseName, n.title AS title, n.content AS content, n.absent_count AS absentCount, DATE_FORMAT(n.send_time, '%Y-%m-%d %H:%i:%s') AS sendTime, CASE WHEN n.read_status = 1 THEN TRUE ELSE FALSE END AS isRead, DATE_FORMAT(n.read_time, '%Y-%m-%d %H:%i:%s') AS readTime FROM attendance_notice n LEFT JOIN course c ON n.course_id = c.course_id WHERE n.student_id = #{studentId} AND n.send_status = 1
AND n.read_status = #{status}
ORDER BY n.send_time DESC, n.notice_id DESC
